const STATUS_OPTIONS = ["New", "Contacted", "Qualified", "Demo Booked", "Proposal Sent", "Demo Done", "Payment Follow Up", "Negotiation", "Renewal", "Renewal Won", "Won", "Lost", "Junk"];
const STAGE_OPTIONS = STATUS_OPTIONS;
