// 🤖 PURE REMARK-BASED AI CLOSING DECISION ENGINE
// Decides win probability 100% based on the exact Note / Remark entered by the user!
const calculateAiWinProbability = (lead, customNotesText = null) => {
  if (!lead) return { percentage: 50, label: "Moderate", color: "#f59e0b", badgeClass: "warm", signals: [] };

  const status = (lead.status || "").toLowerCase().trim();
  if (status === "won" || status === "closed won") {
    return { percentage: 100, label: "Closed Won", color: "#10b981", badgeClass: "hot", signals: ["Deal officially Won!"] };
  }
  if (status === "lost" || status === "closed lost" || status === "junk") {
    return { percentage: 0, label: "Closed Lost", color: "#ef4444", badgeClass: "cold", signals: ["Deal marked as Lost"] };
  }

  // Extract Notes Text safely
  let notesStr = "";
  if (customNotesText !== null && customNotesText !== undefined) {
    notesStr = String(customNotesText);
  } else if (Array.isArray(lead.notes)) {
    notesStr = lead.notes.map(n => {
      if (!n) return "";
      if (typeof n === 'object') return String(n.text || "");
      return String(n);
    }).filter(Boolean).join(" ");
  } else if (lead.notes) {
    notesStr = typeof lead.notes === 'object' ? String(lead.notes.text || "") : String(lead.notes);
  } else if (lead.focusAction) {
    notesStr = String(lead.focusAction);
  }
  
  const rawText = notesStr.toLowerCase().trim();
  const signals = [];

  // If NO remark is written yet:
  if (!rawText || rawText === "") {
    return {
      percentage: 50,
      label: "Pending Remark",
      color: "#94a3b8",
      badgeClass: "warm",
      signals: ["Add Note to predict AI Win %"]
    };
  }

  // 🤖 AI DECISION LOGIC BASED PURELY ON THE REMARK CONTENT:
  let winScore = 50; // Neutral baseline

  // 1. High Intent Payment / Closing Signals (80% to 98% Win)
  const isQrOrLink = /(qr|code|upi|gpay|phonepe|paytm|payment link|link|invoice|bill|bank|account)/i.test(rawText);
  const isShareOrSent = /(share|shared|sent|send|bhej|bheja|diya|dya|di)/i.test(rawText);
  const isAgreedOrDone = /(agreed|approved|ready|done|final|tayyar|haan|yes|advance|paid|contract|signed|renew|renewal|interested|pasand)/i.test(rawText);
  const isPaymentPromised = /(payment|pay|pesa|paisa|remittance|amount)/i.test(rawText) && /(kre ga|karega|krega|karegi|dega|denge|dene|bhejega|bheje ga|bhej|kar dega|kar denge|aaj|kal|ko|parso)/i.test(rawText);

  if ((isQrOrLink && isShareOrSent) || (isQrOrLink && isAgreedOrDone)) {
    winScore = 95;
    signals.push("🟢 Payment QR / Link Shared (High Closing Intent)");
  } else if (isPaymentPromised) {
    winScore = 90;
    signals.push("🟢 Payment Promised by Customer (90% Win)");
  } else if (isAgreedOrDone) {
    winScore = 88;
    signals.push("🟢 Customer Agreed / Deal Approved");
  } else if (isQrOrLink) {
    winScore = 80;
    signals.push("🟢 Payment / Invoice Mentioned");
  }

  // 2. Callback / Delay / Postpone / Hesitant Signals (25% to 45% Win)
  const isCallback = /(call back|callback|call|baat|phone)/i.test(rawText) && /(back|later|baad|bola|baye|krne|karo|plz|pls)/i.test(rawText);
  const isPostponed = /(baad me|baad mai|baad m|busy|meeting|soch|discuss|next week|agle hafte|hold|wait|delay|time chahiye|parso)/i.test(rawText);
  const isDayDeferred = /(tue|tus|mon|wed|thu|fri|sat|sun|tuesday|monday|wednesday|thursday|friday|saturday|sunday)/i.test(rawText);

  if (!isPaymentPromised && (isCallback || isPostponed || (isDayDeferred && !isQrOrLink))) {
    winScore = 35;
    signals.push("🟡 Callback Requested / Decision Postponed");
  }

  // 3. Rejection / Refusal / Wrong Number Signals (5% to 20% Win)
  const isRefused = /(mana|mna|not interested|expensive|mehnga|too high|no budget|cancel|cancelled|wrong|drop)/i.test(rawText);
  if (isRefused) {
    winScore = 10;
    signals.push("🔴 Customer Refused / Objection / Cancelled");
  }

  // Clamp percentage between 5% and 98%
  const finalPct = Math.min(98, Math.max(5, winScore));

  let label = "Moderate";
  let color = "#f59e0b"; // amber
  let badgeClass = "warm";

  if (finalPct >= 75) {
    label = "High Closing Probability";
    color = "#10b981"; // emerald green
    badgeClass = "hot";
  } else if (finalPct >= 45) {
    label = "Moderate / Callback";
    color = "#f59e0b"; // amber
    badgeClass = "warm";
  } else {
    label = "High Risk / Refused";
    color = "#ef4444"; // red
    badgeClass = "cold";
  }

  return {
    percentage: finalPct,
    label,
    color,
    badgeClass,
    signals
  };
};

// Auto AI Remark Generator Helper based on Lead Stage, Follow Up Date & Value
const generateAutoAiRemarkForLead = (lead) => {
  if (!lead) return "New lead created. Awaiting first contact.";

  const status = (lead.status || "new").toLowerCase();
  const rawDate = lead.next_follow_up ? new Date(lead.next_follow_up) : null;
  const followUpDateStr = (rawDate && !isNaN(rawDate.getTime()))
    ? rawDate.toLocaleDateString("en-IN", { day: '2-digit', month: 'short' })
    : String(lead.next_follow_up || "");

  if (status === "won" || status === "closed won") {
    return "🏆 Deal Closed & Won! Payment confirmed.";
  }
  if (status === "lost" || status === "closed lost") {
    return `❌ Deal Lost. Reason: ${lead.lost_reason || "Price / Competitor"}`;
  }
  if (status === "renewal") {
    return followUpDateStr 
      ? `Renewal due. Follow-up & payment promised for ${followUpDateStr}. QR code sent.`
      : "Renewal lead active. QR code & invoice share kiya hua hai.";
  }
  if (status === "payment follow up") {
    return followUpDateStr
      ? `Payment follow-up active. Client promised payment for ${followUpDateStr}.`
      : "Invoice & payment link shared. Awaiting transfer.";
  }
  if (status === "negotiation") {
    return "In negotiation. Proposal & discount terms under review.";
  }
  if (status === "proposal sent") {
    return "Proposal sent via email. Following up on decision.";
  }
  if (status === "demo done") {
    return "Product demo completed. Client showed positive interest.";
  }
  if (status === "qualified") {
    return "Lead qualified. Requirement gathered for proposal.";
  }
  if (status === "contacted") {
    return "Initial contact made. Shared product details.";
  }

  return "New lead added to pipeline. Follow-up scheduled.";
};

// AI Next Best Action (NBA) Prescriber Engine
const getAiNextBestAction = (lead) => {
  if (!lead) return "Contact lead to qualify requirements.";
  const aiResult = calculateAiWinProbability(lead);
  const status = (lead.status || "").toLowerCase();

  if (status === "won") return "🏆 Deal Closed! Onboard client & schedule onboarding call.";
  if (status === "lost") return "❌ Deal Lost. Log lost reason & set reminder for re-engagement in 60 days.";

  if (aiResult.percentage >= 85) {
    return "📲 Priority 1: Send Payment QR Link / Invoice for instant closing!";
  }
  if (aiResult.percentage >= 60) {
    return "📞 Priority 2: Call decision maker today to confirm payment & finalize agreement.";
  }
  if (aiResult.percentage >= 40) {
    return "🎁 Priority 3: Offer limited-time spot discount or address price objection.";
  }
  return "📅 Priority 4: Re-engage client via direct follow-up or reschedule demo.";
};

