// High-performance requestAnimationFrame numeric count-up component
const AnimatedNumber = ({ value, duration = 1000, isCurrency = false, isPercent = false }) => {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    let start = 0;
    const end = Number(value) || 0;
    if (end === 0) {
      setCurrent(0);
      return;
    }
    
    const startTime = performance.now();
    
    const animate = (now) => {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      
      // Easing: easeOutQuad
      const easedProgress = progress * (2 - progress);
      
      const currentVal = Math.round(start + easedProgress * (end - start) * 10) / 10;
      setCurrent(currentVal);
      
      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setCurrent(end);
      }
    };
    
    requestAnimationFrame(animate);
  }, [value, duration]);

  if (isCurrency) {
    return `₹${Math.round(current).toLocaleString("en-IN")}`;
  }
  if (isPercent) {
    return `${current.toFixed(1)}%`;
  }
  return Math.round(current).toLocaleString("en-IN");
};

// SVG Circular Progress Ring Component
function CircularProgress({ percentage, color = "#ea580c", size = 52, strokeWidth = 5 }) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div style={{ position: "relative", width: size, height: size, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="#f1f5f9"
          strokeWidth={strokeWidth}
          fill="transparent"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          fill="transparent"
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          style={{ transition: "stroke-dashoffset 0.5s ease" }}
        />
      </svg>
      <span style={{ position: "absolute", fontSize: `${Math.max(8, Math.round(size * 0.26))}px`, fontWeight: "700", color: "#0f172a", lineHeight: 1 }}>
        {percentage}%
      </span>


    </div>
  );
}
