  const [splitDossierTab, setSplitDossierTab] = useState("overview"); // "overview", "timeline", "ai", "payment"
  const [splitLeadSearch, setSplitLeadSearch] = useState("");
  const [splitLeadFilterStage, setSplitLeadFilterStage] = useState("all");
  const [splitLeadFilterScore, setSplitLeadFilterScore] = useState("all");
  const [splitNewNoteText, setSplitNewNoteText] = useState("");
  const [splitNewNoteType, setSplitNewNoteType] = useState("Call");
  const [splitEditValueMode, setSplitEditValueMode] = useState(false);
  const [splitTempAmount, setSplitTempAmount] = useState("");

  // Deals Hub States
  const [dealsSearchQuery, setDealsSearchQuery] = useState("");
