  const [dealsFilterAmount, setDealsFilterAmount] = useState("all"); // "all", "high", "mid", "low"
  const [dealsDateFilter, setDealsDateFilter] = useState("all"); // "all", "today", "yesterday", "this_week", "this_month", "last_month", "this_quarter", "custom"
  const [dealsStartDate, setDealsStartDate] = useState("");
  const [dealsEndDate, setDealsEndDate] = useState("");
